/**
 * MECHPLANT — Offline Lightweight Charting Engine Shim (Compatible con API Chart.js v4 UMD)
 * Ruta: assets/js/vendor/chartjs/chart.umd.min.js
 * Soporta line, scatter, bar, radar, doughnut, ejes lineales/categóricos, múltiples datasets,
 * rejilla Industrial Blueprint, anotaciones y leyendas para operación 100% offline.
 */
(function (global) {
  "use strict";

  const DEFAULT_PALETTE = [
    "#0095D9",
    "#38BDF8",
    "#F59E0B",
    "#22C55E",
    "#EF4444",
    "#A855F7"
  ];

  class Chart {
    constructor(ctxOrEl, config = {}) {
      this.canvas =
        typeof ctxOrEl === "string"
          ? document.querySelector(ctxOrEl)
          : ctxOrEl && ctxOrEl.canvas
          ? ctxOrEl.canvas
          : ctxOrEl;

      this.ctx = this.canvas ? this.canvas.getContext("2d") : null;
      this.config = config;
      this.type = config.type || "line";
      this.data = config.data || { labels: [], datasets: [] };
      this.options = config.options || {};

      if (this.canvas) {
        this.canvas._mechplantChart = this;
        this._bindResize();
      }
      this.render();
    }

    static register() {
      // Compatibilidad con Chart.register(annotationPlugin, ...)
    }

    _bindResize() {
      if (this._resizeHandler) return;
      this._resizeHandler = () => this.render();
      window.addEventListener("resize", this._resizeHandler);
    }

    update() {
      this.render();
    }

    destroy() {
      if (this._resizeHandler) {
        window.removeEventListener("resize", this._resizeHandler);
        this._resizeHandler = null;
      }
      if (this.ctx && this.canvas) {
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
      }
    }

    _resolveDimensions() {
      const parent = this.canvas.parentElement;
      const rect = parent ? parent.getBoundingClientRect() : { width: 640, height: 320 };
      const w = Math.max(280, Math.floor(rect.width || this.canvas.clientWidth || 640));
      const h = Math.max(200, Math.floor(rect.height || this.canvas.clientHeight || 320));
      const dpr = Math.min(window.devicePixelRatio || 1, 2);

      this.canvas.width = w * dpr;
      this.canvas.height = h * dpr;
      this.canvas.style.width = w + "px";
      this.canvas.style.height = h + "px";
      this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      return { w, h };
    }

    render() {
      if (!this.ctx || !this.canvas) return;
      const { w, h } = this._resolveDimensions();
      const ctx = this.ctx;

      // Fondo Blueprint
      ctx.fillStyle = "#081220";
      ctx.fillRect(0, 0, w, h);

      const pad = { top: 36, right: 24, bottom: 42, left: 56 };
      const plotW = Math.max(60, w - pad.left - pad.right);
      const plotH = Math.max(60, h - pad.top - pad.bottom);

      const datasets = this.data.datasets || [];
      const labels = this.data.labels || [];

      if (datasets.length === 0) {
        ctx.fillStyle = "#94A3B8";
        ctx.font = "12px monospace";
        ctx.textAlign = "center";
        ctx.fillText("Sin datos gráficos disponibles", w / 2, h / 2);
        return;
      }

      // Recolección de puntos (x, y)
      const isScatter = this.type === "scatter";
      let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

      const normalizedSets = datasets.map((ds, dsIdx) => {
        const raw = ds.data || [];
        const pts = raw.map((item, idx) => {
          if (item !== null && typeof item === "object") {
            return { x: Number(item.x ?? idx), y: Number(item.y ?? 0) };
          }
          return { x: idx, y: Number(item ?? 0) };
        });

        pts.forEach((p) => {
          if (Number.isFinite(p.x)) { minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); }
          if (Number.isFinite(p.y)) { minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y); }
        });

        return {
          label: ds.label || `Serie ${dsIdx + 1}`,
          pts,
          borderColor: ds.borderColor || DEFAULT_PALETTE[dsIdx % DEFAULT_PALETTE.length],
          backgroundColor: ds.backgroundColor || DEFAULT_PALETTE[dsIdx % DEFAULT_PALETTE.length],
          fill: Boolean(ds.fill),
          borderDash: Array.isArray(ds.borderDash) ? ds.borderDash : [],
          pointRadius: ds.pointRadius !== undefined ? ds.pointRadius : isScatter ? 4 : 2.5,
          showLine: ds.showLine !== undefined ? ds.showLine : !isScatter
        };
      });

      if (!Number.isFinite(minX)) { minX = 0; maxX = 10; }
      if (!Number.isFinite(minY)) { minY = 0; maxY = 10; }
      if (this.type === "bar") minY = Math.min(0, minY);
      if (maxX === minX) maxX = minX + 1;
      if (maxY === minY) maxY = minY + 1;

      const yMargin = (maxY - minY) * 0.08;
      minY -= yMargin;
      maxY += yMargin;

      const toPxX = (vx) => pad.left + ((vx - minX) / (maxX - minX)) * plotW;
      const toPxY = (vy) => pad.top + plotH - ((vy - minY) / (maxY - minY)) * plotH;

      // Cuadrícula y marcas de ejes
      ctx.strokeStyle = "#163254";
      ctx.lineWidth = 1;
      ctx.fillStyle = "#94A3B8";
      ctx.font = "11px monospace";

      const yTicks = 5;
      for (let i = 0; i <= yTicks; i++) {
        const valY = minY + (i / yTicks) * (maxY - minY);
        const py = toPxY(valY);
        ctx.beginPath();
        ctx.moveTo(pad.left, py);
        ctx.lineTo(pad.left + plotW, py);
        ctx.stroke();

        ctx.textAlign = "right";
        ctx.textBaseline = "middle";
        ctx.fillText(valY.toFixed(1), pad.left - 8, py);
      }

      const xTicks = 5;
      for (let i = 0; i <= xTicks; i++) {
        const valX = minX + (i / xTicks) * (maxX - minX);
        const px = toPxX(valX);
        ctx.beginPath();
        ctx.moveTo(px, pad.top);
        ctx.lineTo(px, pad.top + plotH);
        ctx.stroke();

        ctx.textAlign = "center";
        ctx.textBaseline = "top";
        const labelIdx = Math.round(valX);
        const txt = !isScatter && labels[labelIdx] !== undefined ? String(labels[labelIdx]) : valX.toFixed(1);
        ctx.fillText(txt, px, pad.top + plotH + 8);
      }

      // Ejes principales
      ctx.strokeStyle = "#38BDF8";
      ctx.lineWidth = 1.4;
      ctx.strokeRect(pad.left, pad.top, plotW, plotH);

      // Trazado de datasets
      normalizedSets.forEach((ds, dsIdx) => {
        if (ds.pts.length === 0) return;

        if (this.type === "bar") {
          const groupW = plotW / Math.max(ds.pts.length, 1);
          const barW = Math.max(6, (groupW * 0.72) / normalizedSets.length);
          const zeroY = toPxY(0);

          ds.pts.forEach((p, idx) => {
            const bx = pad.left + idx * groupW + groupW * 0.14 + dsIdx * barW;
            const by = toPxY(p.y);
            ctx.fillStyle = ds.backgroundColor;
            ctx.fillRect(bx, Math.min(by, zeroY), barW - 2, Math.abs(zeroY - by));
          });
          return;
        }

        if (ds.showLine && ds.pts.length > 1) {
          ctx.save();
          ctx.strokeStyle = ds.borderColor;
          ctx.lineWidth = 2;
          ctx.setLineDash(ds.borderDash);
          ctx.beginPath();
          ds.pts.forEach((p, idx) => {
            const px = toPxX(p.x);
            const py = toPxY(p.y);
            if (idx === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
          });
          ctx.stroke();

          if (ds.fill) {
            ctx.lineTo(toPxX(ds.pts[ds.pts.length - 1].x), pad.top + plotH);
            ctx.lineTo(toPxX(ds.pts[0].x), pad.top + plotH);
            ctx.closePath();
            ctx.fillStyle = "rgba(0, 149, 217, 0.16)";
            ctx.fill();
          }
          ctx.restore();
        }

        if (ds.pointRadius > 0) {
          ctx.fillStyle = ds.borderColor;
          ds.pts.forEach((p) => {
            ctx.beginPath();
            ctx.arc(toPxX(p.x), toPxY(p.y), ds.pointRadius, 0, Math.PI * 2);
            ctx.fill();
          });
        }
      });

      // Anotaciones (plugin annotation opcional)
      const annotations =
        this.options.plugins &&
        this.options.plugins.annotation &&
        this.options.plugins.annotation.annotations;

      if (annotations) {
        Object.values(annotations).forEach((ann) => {
          ctx.save();
          ctx.strokeStyle = ann.borderColor || "#EF4444";
          ctx.lineWidth = ann.borderWidth || 1.5;
          ctx.setLineDash(ann.borderDash || [6, 4]);

          if (ann.type === "line" && ann.yMin !== undefined) {
            const ay = toPxY(ann.yMin);
            if (ay >= pad.top && ay <= pad.top + plotH) {
              ctx.beginPath();
              ctx.moveTo(pad.left, ay);
              ctx.lineTo(pad.left + plotW, ay);
              ctx.stroke();
            }
          } else if (ann.type === "line" && ann.xMin !== undefined) {
            const ax = toPxX(ann.xMin);
            if (ax >= pad.left && ax <= pad.left + plotW) {
              ctx.beginPath();
              ctx.moveTo(ax, pad.top);
              ctx.lineTo(ax, pad.top + plotH);
              ctx.stroke();
            }
          }
          ctx.restore();
        });
      }

      // Leyenda superior
      let legendX = pad.left;
      ctx.font = "11px sans-serif";
      ctx.textAlign = "left";
      ctx.textBaseline = "middle";
      normalizedSets.forEach((ds) => {
        ctx.fillStyle = ds.borderColor;
        ctx.fillRect(legendX, 14, 12, 4);
        ctx.fillStyle = "#E2E8F0";
        ctx.fillText(ds.label, legendX + 16, 16);
        legendX += ctx.measureText(ds.label).width + 32;
      });
    }
  }

  global.Chart = Chart;
})(typeof window !== "undefined" ? window : this);
